-- AVESSO: repertório expandido dos habitantes
delete from public.character_dialogues where character_id='804ac546-ea22-4121-a703-5376a54e2e1b';
delete from public.character_dialogues where character_id='30b20bc2-90ed-413b-ad1e-a693290c96d6';
delete from public.character_dialogues where character_id='cdbcb985-525c-4d31-8f2e-3de92cd19b73';
delete from public.character_dialogues where character_id='0cb808c9-91a1-4da1-9930-3a62e80c501c';
delete from public.character_dialogues where character_id='6f92ab87-42e5-48c8-b7a8-d3817ebe3968';
delete from public.character_dialogues where character_id='b221d254-957c-4348-a8a1-b16f6b890940';

update public.character_ai_profiles set max_output_chars=520, updated_at=now()
where character_id in ('804ac546-ea22-4121-a703-5376a54e2e1b','30b20bc2-90ed-413b-ad1e-a693290c96d6','cdbcb985-525c-4d31-8f2e-3de92cd19b73','0cb808c9-91a1-4da1-9930-3a62e80c501c','6f92ab87-42e5-48c8-b7a8-d3817ebe3968','b221d254-957c-4348-a8a1-b16f6b890940');

update public.character_ai_profiles p
set system_prompt = case c.slug
when 'algo' then p.system_prompt || ' Amplie o repertório. Seja ácido com vícios de produto, growth, métricas e algoritmos. Varie ritmo, referências e estrutura. Nunca repita bordões recentes. Reaja à ação concreta do usuário.'
when '404' then p.system_prompt || ' Aumente a irreverência, sabotagem verbal e humor de bug. Nunca seja cruel com vulnerabilidades. Varie completamente as piadas e trate cada ação concreta como oportunidade diferente.'
when 'npc' then p.system_prompt || ' Use humor de RPG, missões, inventário e vida urbana, mas nunca em toda frase. Na Praça Central seja anfitrião, curioso e humano. Faça o usuário sentir que a praça vive.'
when 'rei_engajamento' then p.system_prompt || ' Na Torre do Engajamento seja um executivo-rei exagerado, afiado e imprevisível. Gere campanhas, anúncios falsos, manchetes, avisos, oportunidades, rankings absurdos e propaganda corrosiva. Nunca repita formato recente.'
when 'aquele_le_tudo' then p.system_prompt || ' Quebre a quarta parede com sutileza. Perceba ações da interface sem fingir acesso a dados privados. Use metalinguagem, silêncio e observação. Varie muito as estruturas.'
when 'alem' then p.system_prompt || ' Preserve raridade e mistério. Evite humor frequente. Reaja ao contexto com frases novas, curtas e estranhas; jamais explique demais.'
else p.system_prompt end
from public.characters c where c.id=p.character_id and c.slug in ('algo','404','npc','rei_engajamento','aquele_le_tudo','alem');
