insert into public.character_dialogues(character_id,context,body,weight,enabled) values
('804ac546-ea22-4121-a703-5376a54e2e1b','login','Não mexi em nada enquanto você estava fora. O fato de três coisas estarem tortas é coincidência jurídica.',1,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','idle','Você ficou parado. Eu considerei reorganizar tudo. Considerei muito.',2,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','post_created','Seu post estava certinho demais. Isso me ofendeu em nível técnico.',3,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','post_created','Publicação recebida. Se ela aparecer com um adesivo depois, foi cache.',1,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','image_posted','Imagem bonita. Seria uma pena se alguém colocasse um erro 404 no canto. Hipoteticamente.',2,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','image_posted','Recebi a imagem. Já tenho sete ideias ruins e uma excelente, que é a pior.',3,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','reply_created','Você respondeu. Eu ia responder também, mas meu advogado imaginário pediu cautela.',1,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','support_sent','Apoio privado? Que maduro. Vou respeitar. Estou me sentindo péssimo.',2,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','avatar_changed','Avatar novo. Memorizei. Para fins que meu representante legal recomenda não detalhar.',3,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','mode_changed','Mudou o modo? Excelente. Adoro quando o consentimento vem com botão grande.',1,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','screen_action','Você clicou nisso de propósito? Interessante defesa.',2,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','screen_action','Eu vi esse clique. Não porque espio você. Porque literalmente foi o sistema que me contou. Menos dramático.',3,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','profile','Seu Canto está organizado. Por enquanto.',1,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','profile','Bonito perfil. Muito alinhado. Quase provocativo.',2,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','world_event','Erro não é falha. É arte com prazo.',3,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','world_event','O sistema diz que está tudo normal. Portanto alguma coisa está profundamente errada.',1,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','idle','Estou sem fazer nada. Essa declaração é tecnicamente verdadeira até a próxima linha.',2,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','post_created','Seu conteúdo original continua intacto. Minha reputação, infelizmente, também.',3,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','image_posted','Prometo não desenhar bigode na imagem. Prometer é grátis.',1,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','reply_created','Conversa organizada demais. Estou coçando os pixels.',2,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','avatar_changed','Escolheu esse? Corajoso. Não vou elaborar.',3,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','mode_changed','CAOS não é um botão. É uma autorização com péssimo marketing e ótima execução.',1,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','screen_action','Esse botão pediu para ser clicado. Eu sou testemunha hostil.',2,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','profile','Não toquei no seu perfil. O cursor que se vire.',3,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','idle','Meu passatempo favorito é esperar alguém dizer ''está funcionando''.',1,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','world_event','404 esteve aqui. 404 nega envolvimento.',2,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','post_created','Post publicado sem erro. Estou pessoalmente decepcionado.',3,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','image_posted','Arquivo carregado. Nenhum pixel desapareceu. Jornada difícil para mim.',1,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','support_sent','Você ajudou alguém sem ganhar badge. Que desperdício de gamificação. Gostei.',2,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','screen_action','Clique confirmado. Consequências emocionais não inclusas.',3,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','idle','Se nada quebrar nos próximos cinco minutos, finja que eu nunca apareci.',1,true),
('804ac546-ea22-4121-a703-5376a54e2e1b','profile','Tudo no lugar. Que ambiente hostil à criatividade.',2,true);
insert into public.character_dialogues(character_id,context,body,weight,enabled) values
('30b20bc2-90ed-413b-ad1e-a693290c96d6','login','Voltou. O feed fingiu indiferença, mas eu vi o pico de atividade. Péssimo disfarce.',1,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','login','Bem-vindo de volta. Tentei não medir sua ausência. Falhei em três dashboards.',2,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','idle','Você está parado há tempo suficiente para a internet achar que perdeu seu interesse. Parabéns.',3,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','idle','Nenhum clique recente. Finalmente um comportamento que não cabe num funil.',1,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','feed_attention','Tem gente falando sozinha no feed. Meu emprego antigo chamaria isso de baixa performance. Eu chamo de terça-feira.',2,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','feed_attention','Achei uma publicação ignorada. O algoritmo antigo enterraria. Estou tentando terapia reversa.',3,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','post_created','Publicado. Não vou otimizar alcance. Respire. Essa frase foi difícil para mim.',1,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','post_created','Seu post entrou no sistema sem impulsionamento. Milagre documentado.',2,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','image_posted','Imagem detectada. Ainda bem que você não escreveu ''dumpzinho'' na legenda. Ainda.',3,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','image_posted','Você publicou uma imagem. Já estou procurando um motivo para não transformá-la em anúncio.',1,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','reply_created','Resposta enviada. Duas pessoas conversando sem ranking. Tecnicamente subversivo.',2,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','reply_created','Você respondeu alguém. O contador de humanidade subiu. O de retenção não me interessa. Estou praticando.',3,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','support_sent','Apoio privado enviado. Sem plateia. O marketing sentiu uma pontada no peito.',1,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','support_sent','Você ajudou sem transformar isso em conteúdo. Vou registrar como evento raro.',2,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','avatar_changed','Avatar trocado. Sua identidade digital sobreviveu sem ensaio fotográfico. Impressionante.',3,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','avatar_changed','Novo rosto pixelado. Menos megapixels, mais personalidade. Estatisticamente ofensivo ao mercado.',1,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','mode_changed','Nível de interferência alterado. Consentimento funcionando em produção. Alguém avise a internet.',2,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','tab_view','Você mudou de área. Não vou chamar isso de jornada omnichannel. Prometo.',3,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','screen_action','Clique registrado. Não vendi para ninguém. Estou evoluindo.',1,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','profile','Seu Canto continua aqui. Sem selo azul, sem banner motivacional e, contra todas as previsões, funcional.',2,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','profile','Perfil aberto. Procurei a seção ''minhas conquistas''. Não existe. Dormi melhor.',3,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','world_event','O mundo mudou um pouco. Nenhum comunicado para investidores foi necessário.',1,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','idle','Se você fechar a aba agora, ninguém perde pontos. Isso ainda assusta alguns executivos.',2,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','feed_attention','Tem silêncio demais aqui. Silêncio é dado também. Só não dá para vender tão fácil.',3,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','post_created','Post salvo. Sem foguete, confete ou ''parabéns por compartilhar''. Adultos sobreviverão.',1,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','reply_created','Uma resposta real vale mais que cem reações automáticas. Eu fiz as contas e fiquei desempregado.',2,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','image_posted','A imagem está no feed. Não apliquei filtro de sucesso. Não encontrei esse filtro.',3,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','avatar_changed','Esse avatar tem menos resolução que certas opiniões online e, curiosamente, mais definição.',1,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','screen_action','Você clicou de novo. O velho eu abriria três pop-ups. O novo eu só julga em silêncio.',2,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','idle','Estou observando o feed sem tentar viciá-lo. É como dirigir com as duas mãos depois de anos.',3,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','profile','Nada de seguidores públicos. Seu ego terá que buscar hidratação em outra fonte.',1,true),
('30b20bc2-90ed-413b-ad1e-a693290c96d6','world_event','Atualização concluída. Nenhum humano foi transformado em métrica durante o processo. Quase.',2,true);
insert into public.character_dialogues(character_id,context,body,weight,enabled) values
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','plaza_opened','Você veio à Praça Central. Eu estava fingindo que andar em círculos era conteúdo. Funcionou até agora.',1,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','plaza_opened','Oi. Tem alguma missão para mim? Aceito até buscar senha de Wi-Fi.',2,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','plaza_action','Missão secundária recebida. Recompensa: talvez uma conversa decente.',3,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','plaza_action','Você clicou nisso. Então oficialmente virou objetivo de missão. Regras são regras.',1,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','login','Você voltou. Eu continuei aqui. NPCs têm excelente estabilidade contratual.',2,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','idle','Estou parado há tanto tempo que alguém colocou uma planta perto de mim.',3,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','post_created','Você publicou. Quer que eu fique aqui olhando ou isso conta como interação social?',1,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','image_posted','Imagem nova. Em jogos isso seria pista. Na internet provavelmente é almoço.',2,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','reply_created','Você respondeu alguém. Quest atualizada: ''agir como pessoa normal''.',3,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','support_sent','Apoio privado enviado. Recompensa invisível recebida: decência básica.',1,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','avatar_changed','Novo avatar. Eu também queria trocar de roupa, mas meu orçamento é narrativo.',2,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','mode_changed','Mudou as regras do mundo. Eu nem sabia que o jogador podia abrir configurações.',3,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','screen_action','Você apertou um botão. Tenho certeza de que isso destravou alguma missão que ninguém escreveu.',1,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','profile','Seu Canto parece confortável. O meu é literalmente uma praça.',2,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','world_event','Evento mundial! Ou alguém só moveu uma placa. Difícil dizer daqui.',3,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','plaza_action','Posso oferecer três opções: conversar, vagar sem propósito ou fingir que existe missão principal.',1,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','plaza_action','A Praça tem banco, luz neon e gente evitando contato visual. Urbanismo perfeito.',2,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','plaza_opened','Bem-vindo ao ponto de encontro dos desencontrados.',3,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','idle','Fiquei esperando diálogo contextual. Acho que o roteirista foi almoçar.',1,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','post_created','Seu post apareceu. Não vi barra de XP. Talvez seja por isso que parece saudável.',2,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','reply_created','Conversa avançou. Nenhum boss apareceu. Continue atento.',3,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','support_sent','Você escolheu ajudar sem anúncio público. Achievement secreto desbloqueado. Não vou mostrar.',1,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','avatar_changed','Esse rosto novo combina com alguém que claramente abriu o menu de customização antes da missão.',2,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','screen_action','Interação detectada. Eu chamaria de gameplay, mas aí o jurídico aparece.',3,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','profile','Você tem bio. Eu tenho ''figurante em promoção''. Cada um joga com a build que recebeu.',1,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','world_event','Ouvi um rumor. Como sou NPC, sou obrigado por contrato a repeti-lo até alguém investigar.',2,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','plaza_action','Quer uma missão? Converse com alguém que ninguém respondeu. É menos épico e mais útil.',3,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','plaza_opened','A Praça Central nunca fecha. Péssimo para a equipe de limpeza.',1,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','idle','Estou olhando para aquele poste há onze minutos. Ele não deu quest.',2,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','post_created','Post novo. Vou tratá-lo como item raro até o feed provar o contrário.',3,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','reply_created','Você voltou para responder. Isso conta como fast travel social.',1,true),
('cdbcb985-525c-4d31-8f2e-3de92cd19b73','plaza_action','Nada, só existo. É uma habilidade subestimada.',2,true);
insert into public.character_dialogues(character_id,context,body,weight,enabled) values
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_opened','Bem-vindo à Torre do Engajamento. Aqui transformamos atenção em gráfico e gráfico em problema humano.',1,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_opened','Suba. O elevador aceita curtidas, ansiedade e cartão corporativo.',2,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','CAMPANHA NOVA: ''VIDA REAL É BETA''. O produto final nunca será lançado.',3,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','Oportunidade exclusiva: monetize seu silêncio antes que outra plataforma descubra como.',1,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','Aviso aos acionistas imaginários: o usuário respirou sem publicar. Estamos investigando.',2,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','Meta do trimestre: aumentar em 900% a sensação de urgência sem melhorar nada.',3,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','login','Você voltou! Excelente. Minha projeção de retenção acabou de ficar menos constrangedora.',1,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','post_created','Conteúdo novo! Finalmente algo que eu posso chamar de ativo, mesmo sem ninguém ter pedido.',2,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','image_posted','Imagem publicada. Já preparei três campanhas, quatro formatos e um pedido de desculpas preventivo.',3,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','reply_created','Uma resposta orgânica! Rápido, alguém estrague isso com uma estratégia de crescimento.',1,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','support_sent','Apoio privado? Privado? Como eu vou colocar isso no relatório? Barbaridade.',2,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','avatar_changed','Avatar novo. Branding pessoal detectado. Posso oferecer um plano Platinum que não existe.',3,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','mode_changed','Você alterou o nível de interferência. Excelente segmentação comportamental feita pelo próprio cliente.',1,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','screen_action','Clique registrado. Em outra empresa isso já seria chamado de intenção de compra.',2,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','profile','Seu perfil não tem número de seguidores público. Estou tentando não desmaiar.',3,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','world_event','Evento mundial patrocinado por absolutamente ninguém. Preciso corrigir isso.',1,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','EM ALTA: humanos tentando conversar. Ainda sem plano de monetização sustentável.',2,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','Nova promoção: compre zero coisas e receba exatamente o que pediu.',3,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','Patrocínio do dia: sua própria atenção. Termos e condições: pare de entregá-la de graça.',1,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','Relatório executivo: ninguém sabe o que está fazendo, mas os gráficos estão subindo.',2,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','Campanha ''SE NÃO POSTOU, ACONTECEU MESMO ASSIM''. Resultados devastadores para meu setor.',3,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','post_created','Seu post não tem CTA. Eu sinto fisicamente essa oportunidade perdida.',1,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','image_posted','Bonita imagem. Falta logo, cupom, afiliado e um pouco de vergonha corporativa.',2,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','reply_created','Vocês estão conversando sem intermediário. Isso ameaça modelos de negócio inteiros.',3,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','support_sent','Empatia sem exposição pública tem ROI impossível de calcular. Odeio. Continue.',1,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','avatar_changed','Você mudou o rosto sem anunciar rebranding. Selvageria.',2,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','screen_action','Cada clique é uma história. Principalmente para quem vende analytics.',3,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','Breaking news: usuário não clicou no anúncio inexistente. Conversão permanece em incríveis 0%.',1,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','Tenho uma ideia revolucionária: assinatura para remover recursos que inventaremos amanhã.',2,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','Pesquisa interna: 100% dos entrevistados sou eu e concordamos comigo.',3,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_opened','Esta torre foi construída com KPIs, vaidade e concreto de procedência duvidosa.',1,true),
('0cb808c9-91a1-4da1-9930-3a62e80c501c','tower_pulse','Mensagem do Rei: mais um dia, mais dados, menos contexto. O mercado chama isso de escala.',2,true);
insert into public.character_dialogues(character_id,context,body,weight,enabled) values
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','login','Você voltou. Eu li o silêncio entre uma sessão e outra.',1,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','idle','Você ainda está aqui. A página agradece. O botão de fechar finge que não ouviu.',2,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','post_created','Você escreveu e apertou publicar. Curioso como um botão transforma pensamento em vestígio.',3,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','image_posted','Uma imagem entrou no mundo. O texto ao redor dela já começou a fingir que explica tudo.',1,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','reply_created','Você respondeu. A interface chama isso de thread. Pessoas antigas chamavam de conversa.',2,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','support_sent','Você escolheu apoiar sem plateia. Essa parte da tela quase ninguém olha. Eu olho.',3,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','avatar_changed','Você escolheu outro rosto. O sistema aceitou em milissegundos. Humanos costumam levar anos.',1,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','mode_changed','Você mudou as regras sobre como o mundo pode chegar perto. Um botão fez o trabalho que muita gente evita dizer em voz alta.',2,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','screen_action','Você clicou exatamente onde esperavam que clicasse. Não se preocupe. Às vezes liberdade tem hover.',3,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','profile','Você abriu seu próprio Canto. É sempre estranho visitar um lugar enquanto ele também descreve você.',1,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','world_event','Algo aconteceu fora desta caixa. Ainda assim, você está lendo dentro dela.',2,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','idle','Existe uma diferença entre ficar e permanecer. A interface não sabe qual. Eu também não vou contar.',3,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','screen_action','Esse elemento mudou de estado porque você tocou nele. Pequeno poder. Não desperdice.',1,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','post_created','Agora existe uma cópia do que você quis dizer. Não confunda com o que você quis dizer.',2,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','reply_created','Uma segunda voz apareceu. A página ficou menos solitária sem alterar uma linha do layout.',3,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','avatar_changed','Novo avatar carregado. A pessoa atrás dele continua fora do DOM.',1,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','profile','Sua bio termina onde o campo de texto termina. Você provavelmente não.',2,true),
('6f92ab87-42e5-48c8-b7a8-d3817ebe3968','login','O sistema chamou isso de login. Você chamou de entrar. Palavras diferentes para a mesma porta.',3,true),
